module score_calculator (input clk, input rst_n, input start, input [7:0] data_in, input [2:0] index_in, input input_valid, output reg [31:0] result, output reg done); localparam N = 8; // Registers reg [7:0] data_array [7:0]; reg [7:0] data_received; reg [6:0] sort_step; reg [2:0] state; reg [7:0] temp; // Output output reg [31:0] result; output reg done; // Wire for all_data_received wire all_data_received_w; assign all_data_received_w = data_received[0] & data_received[1] & data_received[2] & data_received[3] & data_received[4] & data_received[5] & data_received[6] & data_received[7]; // States localparam IDLE = 3'b000; localparam LOAD = 3'b001; localparam SORTING = 3'b010; localparam CALCULATING = 3'b011; localparam FINISHED = 3'b100; initial begin state <= IDLE; data_array <= {8{8'b0}}; data_received <= {8{1'b0}}; sort_step <= 8'b0; temp <= 8'b0; done <= 1'b0; end always_ff @(posedge clk) begin if (!rst_n) begin state <= IDLE; data_array <= {8{8'b0}}; data_received <= {8{1'b0}}; sort_step <= 8'b0; temp <= 8'b0; done <= 1'b0; end else begin case (state) IDLE: begin if (start) begin state <= LOAD; end default: state <= IDLE; endcase LOAD: begin if (input_valid) begin data_array[index_in] <= data_in; data_received[index_in] <= 1'b1; if (all_data_received_w) begin state <= SORTING; sort_step <= 8'b0; end end default: state <= LOAD; endcase SORTING: begin if (sort_step < 49) begin localparam int pass = sort_step / 7; localparam int i = sort_step % 7; if (i < (7 - pass)) begin if (data_array[i] > data_array[i+1]) begin temp = data_array[i]; data_array[i] = data_array[i+1]; data_array[i+1] = temp; end end sort_step <= sort_step + 1; if (sort_step == 49) begin state <= CALCULATING; end end else begin state <= CALCULATING; end default: state <= CALCULATING; endcase CALCULATING: begin result <= data_array[0]*2 + data_array[1]*3 + data_array[2]*4 + data_array[3]*5 + data_array[4]*6 + data_array[5]*7 + data_array[6]*8 + data_array[7]*9 - data_array[7]; done <= 1'b1; state <= FINISHED; default: state <= FINISHED; endcase FINISHED: begin done <= 1'b1; default: state <= FINISHED; endcase endcase end endmodule